/**
 * Small helper: parallelize a traverser over its outermost dimension
 *
 * We use the pattern recommended in the Noarr documentation:
 *
 *   #pragma omp parallel for
 *   for (auto inner_trav : trav)
 *       inner_trav.for_each(f);
 *
 * This keeps the inner i/j loop expressed via `for_each`, as required,
 * while OpenMP distributes the outer dimension across threads.
 */
template<typename TraverserT, typename Func>
inline void parallel_trav_for_each(TraverserT trav, const Func &func) {
	// If the compiler is not invoked with -fopenmp, this pragma is ignored
	// and the code falls back to the sequential behavior.
	#pragma omp parallel for schedule(static)
	for (auto inner_trav : trav) {
		inner_trav.for_each(func);
	}
}


// Array initialization
void init_array(auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	const std::size_t n = A | get_length<'i'>();
	const num_t n_val = static_cast<num_t>(n); // keep original division semantics

	// Traverse jointly over A and B. The outermost dimension is 'i' (rows),
	// which we parallelize over. Each inner_trav then iterates all 'j'
	// indices in its row using for_each.
	parallel_trav_for_each(traverser(A, B), [=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = ((num_t)i * (num_t)(j + 2) + (num_t)2) / n_val;
		B[state] = ((num_t)i * (num_t)(j + 3) + (num_t)3) / n_val;
	});
}


