	using namespace noarr;

	// A, B: i x j
	const std::size_t n = A | get_length<'i'>();
	const std::size_t inner_len = n - 2; // number of interior points in each dimension

	// We will only update interior points [1 .. n-2] x [1 .. n-2].
	// This proto-structure defines that interior region.
	const auto interior_region =
		noarr::slice<'i'>(1, inner_len) ^
		noarr::slice<'j'>(1, inner_len);

	const num_t alpha = (num_t)0.2;

#pragma scop
	for (int t = 0; t < tsteps; t++) {

		// ------------------------------------------------------------------
		// First sweep: B := stencil(A)
		//
		// We traverse only the interior region of A. The traverser provides
		// an outer loop over 'i' (rows), which we parallelize using OpenMP.
		// For each fixed row, the inner `for_each` walks 'j' (columns) in
		// increasing order, i.e., contiguous memory, preserving good locality.
		// ------------------------------------------------------------------
		parallel_trav_for_each(
			traverser(A).order(interior_region),
			[&](auto state) {
				// state contains interior indices (i, j)
				// Use index-state arithmetic to get 4-point neighbors:
				auto west  = state - idx<'j'>(1);
				auto east  = state + idx<'j'>(1);
				auto south = state + idx<'i'>(1);
				auto north = state - idx<'i'>(1);

