// Main computational kernel
//
// Optimizations:
//  - We keep the mathematical scheme identical to the original
//    (two Jacobi sweeps per time step: A -> B, then B -> A).
//  - Interior points are traversed in cache- and SIMD-friendly tiles
//    using `noarr::into_blocks` and `noarr::hoist`, but the user-visible
//    indices remain plain ('i','j') thanks to `traverser(...).order(...)`.
//  - Tiling factors are chosen at run time so that they exactly divide
//    the interior extent; when that is not possible, the tile size
//    gracefully falls back to 1 (no tiling), guaranteeing correctness.
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	auto n = A | get_length<'i'>();
	if (n <= 2) {
		// No interior points, nothing to do
		return;
	}

	auto inner_len = n - 2; // number of interior points in each dimension

	// Heuristic: choose reasonably large tiles, but require that the
	// tile size divides the interior length so that plain
	// `noarr::into_blocks` can be used (no dynamic/border handling).
	constexpr std::size_t max_block_i = 32; // tile height
	constexpr std::size_t max_block_j = 64; // tile width

	auto choose_block = [](std::size_t len, std::size_t max_block) -> std::size_t {
		// Start from min(max_block, len) and shrink until it divides len.
		std::size_t block = max_block;
		if (block > len)
			block = len;

		if (block == 0)
			return std::size_t(1);

		while (block > 1 && (len % block) != 0)
			--block;

		return block; // always >= 1
	};

	const std::size_t block_i = choose_block(inner_len, max_block_i);
	const std::size_t block_j = choose_block(inner_len, max_block_j);

	// Restrict traversal to the interior domain:
	//   i in [1, n-2], j in [1, n-2]
	//
	// Using slices here removes boundary points from the iteration
	// space entirely; no bounds checks are needed inside the kernel.
	auto interior =
		noarr::slice<'i'>(1, inner_len) ^
		noarr::slice<'j'>(1, inner_len);

	// Spatial tiling:
	//   - First split 'i' into block index 'I' and in-block index (also 'i').
	//   - Then split 'j' into block index 'J' and in-block index 'j'.
	//   - Finally hoist 'J' and 'I' so that the traversal order becomes:
	//         for J (tile columns)
	//           for I (tile rows)
	//             for i (rows inside tile)
	//               for j (cols inside tile)
	//
	//   Thanks to `order(...)`, the state seen by the lambda still only
	//   contains 'i' and 'j'; the block indices are purely a traversal
	//   concern and are not exposed.
	auto tiling =
		noarr::into_blocks<'i', 'I', 'i'>(block_i) ^
		noarr::into_blocks<'j', 'J', 'j'>(block_j) ^
		// hoist 'J' first, then 'I' so that 'I' ends up as the
		// outermost dimension: I, J, i, j
		noarr::hoist<'J'>() ^
		noarr::hoist<'I'>();

	const num_t coeff = (num_t)0.2;

#pragma scop
	for (int t = 0; t < tsteps; t++) {
		// First sweep: B := stencil(A)
		noarr::traverser(A)
			.order(interior ^ tiling)
			.for_each([&](auto state) {
				// Center + 4-point stencil over A
				auto west  = state - idx<'j'>(1);
				auto east  = state + idx<'j'>(1);
				auto south = state + idx<'i'>(1);
				auto north = state - idx<'i'>(1);

				B[state] = coeff * (
					A[state] + A[west] + A[east] + A[south] + A[north]
				);
			});

		// Second sweep: A := stencil(B)
		noarr::traverser(B)
			.order(interior ^ tiling)
			.for_each([&](auto state) {
				auto west  = state - idx<'j'>(1);
				auto east  = state + idx<'j'>(1);
				auto south = state + idx<'i'>(1);
				auto north = state - idx<'i'>(1);

				A[state] = coeff * (
					B[state] + B[west] + B[east] + B[south] + B[north]
				);
			});
	}
#pragma endscop
}

